import React from 'react';
import {fireEvent, render} from '@testing-library/react-native';
import RulesDocumentView from '../RulesDocumentView';
import {Theme} from '../../../types/interfaces';

const theme: Theme = {
  name: 'dark',
  backgroundColor: '#000',
  foregroundColor: '#fff',
  dividerColor: '#333',
  translucentBackgroundColor: 'rgba(0,0,0,0.5)',
};

describe('RulesDocumentView', () => {
  it('navigates to internal anchor when link run is pressed', () => {
    const onAnchorNavigation = jest.fn();
    const {getByTestId} = render(
      <RulesDocumentView
        sections={[
          {
            id: 'intro',
            title: 'Introduction',
            level: 1,
            anchor: 'introduction',
            pageRef: 1,
            blocks: [
              {type: 'heading', textRuns: [{text: 'Introduction'}]},
              {
                type: 'paragraph',
                textRuns: [{text: 'See chapter 2', href: '#chapter-2'}],
              },
            ],
          },
        ]}
        query=""
        theme={theme}
        onAnchorNavigation={onAnchorNavigation}
      />,
    );

    fireEvent.press(getByTestId('rules-inline-link-introduction-0-0'));
    expect(onAnchorNavigation).toHaveBeenCalledWith('chapter-2');
  });

  it('shows section page badge for provenance', () => {
    const {getByText} = render(
      <RulesDocumentView
        sections={[
          {
            id: 'intro',
            title: 'Introduction',
            level: 1,
            anchor: 'introduction',
            pageRef: 7,
            blocks: [
              {type: 'heading', textRuns: [{text: 'Introduction'}]},
              {type: 'paragraph', textRuns: [{text: 'Welcome.'}]},
            ],
          },
        ]}
        query=""
        theme={theme}
      />,
    );

    expect(getByText('Page 7')).toBeTruthy();
  });

  it('renders emphasis traits from rules text runs', () => {
    const {getByTestId} = render(
      <RulesDocumentView
        sections={[
          {
            id: 'intro',
            title: 'Introduction',
            level: 1,
            anchor: 'introduction',
            pageRef: 7,
            blocks: [
              {type: 'heading', textRuns: [{text: 'Introduction'}]},
              {
                type: 'paragraph',
                textRuns: [
                  {text: 'Bold', bold: true, href: '#chapter-2'},
                  {text: ' and '},
                  {text: 'Italic', italic: true, href: '#chapter-3'},
                ],
              },
            ],
          },
        ]}
        query=""
        theme={theme}
      />,
    );

    expect(getByTestId('rules-inline-link-introduction-1-0').props.style).toEqual(
      expect.objectContaining({fontWeight: '700'}),
    );
    expect(getByTestId('rules-inline-link-introduction-1-2').props.style).toEqual(
      expect.objectContaining({fontStyle: 'italic'}),
    );
  });
});
